import withNuxt from './.nuxt/eslint.config.mjs'

export default withNuxt({
  // `apphost/`, `desktop/`, and `site/` are separate packages, each installed
  // from inside its own directory. Most of `apphost/` is generated by Aspire
  // anyway, and `desktop/` must stay out of the root install entirely —
  // `electron` is a several-hundred-megabyte dependency and the root install
  // is what the Dockerfile runs. `site/` is the Website, built by Vercel; the
  // one plain module of it with logic in it is tested from `tests/unit/site/`.
  ignores: ['worker/**', 'apphost/**', 'desktop/**', 'site/**', 'data/**', '.scratch/**'],
})
